+test("consume takes the batch that expires first (FEFO)", () => {
+  const store = fresh();
+  // Milk: lot HD-1022 (2 l, expires 2026-10-29) goes before HD-1026 (expires 2026-11-02).
+  const lot = (id) => store.data.batches.find((b) => b.id === id).lot;
+  const used = consume(store, 2, 3, { at, ref: "test" });
+  assert.deepEqual(
+    used.map((u) => ({ lot: lot(u.batchId), qty: u.qty })),
+    [{ lot: "HD-1022", qty: 2 }, { lot: "HD-1026", qty: 1 }],
+  );
+});
+
+test("consume order: no expiry last, then received first, then lower id", () => {
+  const store = fresh();
+  const base = { itemId: 4, lot: "T", qty: 1, location: "dry" };
+  store.data.batches = [
+    { ...base, id: 101, receivedOn: "2026-10-01", expires: null },
+    { ...base, id: 102, receivedOn: "2026-10-20", expires: "2026-12-01" },
+    { ...base, id: 104, receivedOn: "2026-10-10", expires: "2026-12-01" },
+    { ...base, id: 103, receivedOn: "2026-10-10", expires: "2026-12-01" },
+    { ...base, id: 105, receivedOn: "2026-10-25", expires: "2026-11-20" },
+  ];
+  const used = consume(store, 4, 5, { at, ref: "test" });
+  assert.deepEqual(used.map((u) => u.batchId), [105, 103, 104, 102, 101]);
+});
